-- App 0.107.0: quatro opções do Jev vêm embutidas, sem interruptor, nos planos
-- Pro e Enterprise e para o admin do sistema: manter o chat no modelo da sessão
-- (`keepSessionModel`), retomar os pedidos quando o limite de uso volta
-- (`limitResume`), uma sessão entre planejamento e build (`planBuildSession`) e
-- o tempo máximo do pedido decidido pelo Jev (`autoTurnCeiling`). São recursos
-- do catálogo travados nesses planos; o Free não os recebe e segue com os
-- interruptores de hoje. `my_features()` trava os quatro também para o admin
-- (o resto continua livre para ele).

on conflict (key) do nothing;

select p.key, f.key, 'locked', true
from public.plans p
cross join public.features f
where p.key in ('pro', 'enterprise') and f.key in ('keepSessionModel', 'limitResume', 'planBuildSession', 'autoTurnCeiling')
on conflict (plan_key, feature_key) do update set mode = 'locked', default_on = true;

create or replace function public.my_features() returns jsonb language sql stable security definer set search_path = '' as $$
  with mine as (select public.my_plan() as plan_key),
  me as (select coalesce(public.is_admin(), false) as admin),
  included as (
    select f.key, f.position, pf.mode, pf.default_on
    from public.features f
    left join public.plan_features pf on pf.feature_key = f.key and pf.plan_key = (select plan_key from mine)
    where case when (select admin from me) then true else f.enabled and pf.feature_key is not null end
  )
  select jsonb_build_object(
    'plan', (select plan_key from mine),
    'admin', (select admin from me),
    'managed', true,
    'features', coalesce((select jsonb_agg(key order by position, key) from included), '[]'::jsonb),
    'locked', coalesce((select jsonb_agg(key order by position, key) from included
                        where case when (select admin from me) then key in ('keepSessionModel', 'limitResume', 'planBuildSession', 'autoTurnCeiling') else mode = 'locked' end), '[]'::jsonb),
    'defaults', coalesce((select jsonb_object_agg(key, coalesce(default_on, true)) from included where mode is distinct from 'locked' or (select admin from me)), '{}'::jsonb),
    'limits', (select jsonb_build_object('jevDailyLimit', p.jev_daily_limit, 'maxConcurrentTurns', p.max_concurrent_turns)
               from public.plans p where p.key = (select plan_key from mine))
  );
$$;

on conflict (locale, key) do update set value = excluded.value;

-- Uma frase a mais no manual do limite de uso, em cada idioma (uma vez só).
update public.translations set value = to_jsonb((value #>> '{}') || $s$ Nos planos Pro e Enterprise e para o admin do sistema, ela vem embutida: sempre ligada e sem interruptor.$s$) where locale = 'pt-BR' and key = 'docs.limitResume.usage' and (value #>> '{}') not like '%' || $s$Nos planos Pro e Enterprise e para o admin do sistema, ela vem embutida: sempre ligada e sem interruptor.$s$ || '%';
update public.translations set value = to_jsonb((value #>> '{}') || $s$ On Pro, Enterprise and system admin accounts it is built in: always on and without a switch.$s$) where locale = 'en' and key = 'docs.limitResume.usage' and (value #>> '{}') not like '%' || $s$On Pro, Enterprise and system admin accounts it is built in: always on and without a switch.$s$ || '%';
update public.translations set value = to_jsonb((value #>> '{}') || $s$ En Pro, Enterprise y para el admin del sistema viene integrada: siempre activa y sin interruptor.$s$) where locale = 'es' and key = 'docs.limitResume.usage' and (value #>> '{}') not like '%' || $s$En Pro, Enterprise y para el admin del sistema viene integrada: siempre activa y sin interruptor.$s$ || '%';
